import json
import os


class JSONProcessor:
    READ_SUCCESS = 1
    READ_FAIL_FILE_NOT_FOUND = 0
    READ_FAIL_ERROR = -1
    WRITE_SUCCESS = 1
    WRITE_FAIL_ERROR = -1

    def read_json(self, file_path):
        if not os.path.exists(file_path):
            return self.READ_FAIL_FILE_NOT_FOUND
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
            return data
        except Exception:
            return self.READ_FAIL_ERROR

    def write_json(self, data, file_path):
        try:
            with open(file_path, 'w') as file:
                json.dump(data, file)
            return self.WRITE_SUCCESS
        except Exception:
            return self.WRITE_FAIL_ERROR

    def process_json(self, file_path, remove_key):
        read_result = self.read_json(file_path)
        if read_result == self.READ_FAIL_FILE_NOT_FOUND or read_result == self.READ_FAIL_ERROR:
            return 0
        if self.has_key(read_result, remove_key):
            self.remove_key_from_data(read_result, remove_key)
            write_result = self.write_json(read_result, file_path)
            return 1 if write_result == self.WRITE_SUCCESS else 0
        else:
            return 0

    def has_key(self, data, key):
        return key in data

    def remove_key_from_data(self, data, key):
        if key in data:
            del data[key]

    def collect_data(self, file_path):
        data = self.read_json(file_path)
        if data == self.READ_FAIL_FILE_NOT_FOUND or data == self.READ_FAIL_ERROR:
            return None
        return data
